null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La situación","cuerpo":["La estancia tiene 5.000 hectáreas, la mitad con bosque nativo en categoría amarilla de la Ley de Bosques. Tiene 1.000 vacas y desteta 600 terneros por año. Cada vaca emite unos 80 kg de metano por año. En la última sequía perdió animales por falta de forraje. Un comprador europeo le pide demostrar que su carne no viene de tierras desmontadas después de 2020."]},"solucion":{}},{"slug":"alimentacion-5.s7.p2","orden":2,"grupo":"alimentacion-5.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kg de metano corresponden hoy a cada ternero destetado? Redondeá al entero.","unidad":"kg de metano","decimales":0,"contexto":"1.000 vacas; 80 kg de metano cada una; 600 terneros."},"solucion":{"valor":133,"tolerancia":2.66,"explicacion":"1.000 × 80 = 80.000 kg; ÷ 600 ≈ 133 kg por ternero."}},{"slug":"alimentacion-5.s7.p3","orden":3,"grupo":"alimentacion-5.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si mejora la sanidad y la reproducción y llega a 800 terneros por año con las mismas vacas, ¿cuántos kg de metano por ternero serían?","unidad":"kg de metano","decimales":0,"contexto":"80.000 kg de metano; 800 terneros."},"solucion":{"valor":100,"tolerancia":2,"explicacion":"80.000 ÷ 800 = 100 kg por ternero: una reducción del 25 % en la intensidad."}},{"slug":"alimentacion-5.s7.p4","orden":4,"grupo":"alimentacion-5.s7.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá las propuestas.","grupos":[{"id":"g1","nombre":"Conviene"},{"id":"g2","nombre":"No conviene"}],"items":[{"id":"i1","texto":"Manejo del bosque con ganadería integrada, sin desmontar"},{"id":"i2","texto":"Desmontar el bosque amarillo para hacer pasturas"},{"id":"i3","texto":"Reservas de forraje para las sequías"},{"id":"i4","texto":"Comprar terneros de campos sin trazabilidad"},{"id":"i5","texto":"Registrar coordenadas y movimientos de los animales"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Producir más sin desmontar, prepararse para la sequía y poder demostrar el origen."}},{"slug":"alimentacion-5.s7.p5","orden":5,"grupo":"alimentacion-5.s7.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué no conviene desmontar el bosque de categoría amarilla para ampliar pasturas?","opciones":[{"id":"o1","texto":"La ley no lo permite y quedaría fuera del mercado"},{"id":"o2","texto":"Porque el bosque no sirve para nada"},{"id":"o3","texto":"Porque así tendría menos vacas"},{"id":"o4","texto":"Porque las pasturas no crecen en el Chaco"}]},"solucion":{"clave":["o1"],"explicacion":"En zona amarilla se permite el uso sostenible, no el desmonte; y el comprador exige no desmonte.","por_opcion":{"o3":"El problema no es la cantidad de vacas: es la ley y el mercado."}}},{"slug":"alimentacion-5.s7.p6","orden":6,"grupo":"alimentacion-5.s7.p6","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué debería registrar la estancia para demostrar el origen de su carne? Marcá todo.","opciones":[{"id":"o1","texto":"Coordenadas de sus campos"},{"id":"o2","texto":"Movimientos de los animales entre campos"},{"id":"o3","texto":"Origen de los terneros que compra"},{"id":"o4","texto":"Imágenes que muestren que no hubo desmonte después de 2020"},{"id":"o5","texto":"Solo el nombre del último campo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La trazabilidad completa es la condición para acceder a mercados exigentes."}},{"slug":"alimentacion-5.s7.p7","orden":7,"grupo":"alimentacion-5.s7.p7","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Mejorar la reproducción del rodeo reduce el metano total aunque no cambie la cantidad de vacas.","razones":[{"id":"r1","texto":"Porque baja la intensidad, no el total"},{"id":"r2","texto":"Porque los terneros absorben metano"},{"id":"r3","texto":"Porque las vacas preñadas no emiten"}]},"solucion":{"valor":false,"explicacion":"El metano total casi no cambia con las mismas vacas: lo que baja es la intensidad, el metano por ternero producido.","clave":["r1"]}},{"slug":"alimentacion-5.s7.p8","orden":8,"grupo":"alimentacion-5.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La estancia redacta su plan. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Aplicaremos manejo de bosque con ganadería integrada."},{"id":"s2","texto":"Desmontaremos 500 hectáreas de bosque amarillo para pasturas."},{"id":"s3","texto":"Guardaremos reservas de forraje para la próxima sequía."},{"id":"s4","texto":"Diremos que la carne es carbono neutral sin medir nada."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan produce más, conserva el bosque, se prepara para el clima y comunica con honestidad.","por_opcion":{"s2":"No está permitido en zona amarilla y la dejaría fuera del mercado europeo.","s4":"Una promesa sin mediciones es greenwashing."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"alimentacion-6","rama":"alimentacion","orden":6,"nivel":3,"titulo_es":"Seguridad alimentaria","bajada_es":"Hambre, obesidad, precios y comedores: qué significa que todas las personas puedan comer bien, siempre, y qué hace falta para que un sistema alimentario resista las crisis.","objetivos_es":["Explicar las cuatro dimensiones de la seguridad alimentaria","Interpretar los datos mundiales de hambre e inseguridad alimentaria","Analizar la doble carga de malnutrición y el papel de los entornos alimentarios","Relacionar ingresos, canastas y acceso a los alimentos en Argentina","Proponer medidas para sistemas alimentarios resilientes y justos"],"repasa":["alimentacion-1","alimentacion-3","alimentacion-5","consumo-4"],"requiere_tronco":3,"fuentes":["fao-sofi","fao-hambre-2025","indec-pobreza-2025","ennys2","ley-27642-etiquetado","guias-alimentarias-ar","red-bancos-alimentos","via-campesina","fao-sofa-2023"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"alimentacion-6.s1","orden":1,"tipo":"leccion","titulo_es":"Qué es la seguridad alimentaria","bajada_es":"Disponibilidad, acceso, utilización y estabilidad: no alcanza con que haya comida en el país.","minutos":10,"pasos":[{"slug":"alimentacion-6.s1.p1","orden":1,"grupo":"alimentacion-6.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuatro dimensiones","cuerpo":["Según la FAO, hay seguridad alimentaria cuando todas las personas tienen, en todo momento, acceso físico y económico a alimentos suficientes, inocuos y nutritivos para llevar una vida activa y sana. Eso tiene cuatro dimensiones. Disponibilidad: que haya alimentos. Acceso: que las personas puedan conseguirlos, con ingresos o de otras formas. Utilización: que el cuerpo pueda aprovecharlos, con agua segura, higiene, salud y conocimientos. Y estabilidad: que todo eso se sostenga en el tiempo, también en crisis."],"lista":["Disponibilidad","Acceso","Utilización","Estabilidad"]},"solucion":{}},{"slug":"alimentacion-6.s1.p2","orden":2,"grupo":"alimentacion-6.s1.p2","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué dimensión de la seguridad alimentaria falla en cada caso?","grupos":[{"id":"g1","nombre":"Disponibilidad"},{"id":"g2","nombre":"Acceso"},{"id":"g3","nombre":"Utilización"},{"id":"g4","nombre":"Estabilidad"}],"items":[{"id":"i1","texto":"Una sequía destruye la cosecha de una región aislada"},{"id":"i2","texto":"Hay comida en el almacén, pero la familia no puede pagarla"},{"id":"i3","texto":"Un chico con diarrea por agua contaminada no aprovecha lo que come"},{"id":"i4","texto":"Los precios de los alimentos suben de golpe cada pocos meses"},{"id":"i5","texto":"No llegan alimentos a un pueblo por un corte de rutas"},{"id":"i6","texto":"La verdulería más cercana queda a 20 km"},{"id":"i7","texto":"Una familia no sabe cómo preparar alimentos variados"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g4","i5":"g1","i6":"g2","i7":"g3"},"explicacion":"Muchas veces el problema no es que falte comida en el país, sino el acceso."}},{"slug":"alimentacion-6.s1.p3","orden":3,"grupo":"alimentacion-6.s1.p3","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Argentina produce alimentos para muchas más personas que las que viven en el país. ¿Por qué igual hay personas con hambre?","opciones":[{"id":"o1","texto":"Porque no todas pueden acceder a esos alimentos"},{"id":"o2","texto":"Porque los alimentos producidos no son comestibles"},{"id":"o3","texto":"Porque el país no produce ningún alimento"},{"id":"o4","texto":"Porque el hambre no existe en países productores"}]},"solucion":{"clave":["o1"],"explicacion":"Producir no alcanza: la seguridad alimentaria depende sobre todo del acceso.","por_opcion":{"o3":"Es un gran productor y exportador de alimentos."}}},{"slug":"alimentacion-6.s1.p4","orden":4,"grupo":"alimentacion-6.s1.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Hambre e inseguridad alimentaria","cuerpo":["El hambre, o subalimentación, es no consumir de forma habitual la energía necesaria para una vida activa. La inseguridad alimentaria es más amplia: incluye a quienes tienen que reducir la calidad o la cantidad de lo que comen por falta de dinero u otros recursos, aunque no pasen hambre todos los días. Se mide con encuestas que preguntan, por ejemplo, si en el último año alguien del hogar tuvo que saltearse comidas o comer menos de lo necesario."]},"solucion":{}},{"slug":"alimentacion-6.s1.p5","orden":5,"grupo":"alimentacion-6.s1.p5","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená estas situaciones de menor a mayor gravedad de la inseguridad alimentaria.","items":[{"id":"i1","texto":"Preocupación por poder comprar comida a fin de mes"},{"id":"i2","texto":"Comer menos variado por falta de dinero"},{"id":"i3","texto":"Saltearse comidas algunos días"},{"id":"i4","texto":"Pasar un día entero sin comer"}],"extremos":["Menos grave","Más grave"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La inseguridad alimentaria es una escala: empieza con la preocupación y puede llegar al hambre."}},{"slug":"alimentacion-6.s1.p6","orden":6,"grupo":"alimentacion-6.s1.p6","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada dimensión con una política que la fortalece.","izquierda":[{"id":"a1","texto":"Disponibilidad"},{"id":"a2","texto":"Acceso"},{"id":"a3","texto":"Utilización"},{"id":"a4","texto":"Estabilidad"}],"derecha":[{"id":"b1","texto":"Apoyar la producción local de alimentos"},{"id":"b2","texto":"Transferencias de ingresos y comedores"},{"id":"b3","texto":"Agua segura y educación alimentaria"},{"id":"b4","texto":"Reservas y protección frente a crisis de precios"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Una estrategia completa atiende las cuatro dimensiones."}},{"slug":"alimentacion-6.s1.p7","orden":7,"grupo":"alimentacion-6.s1.p7","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un país produce más alimentos de los que consume, toda su población tiene seguridad alimentaria.","razones":[{"id":"r1","texto":"Porque importan también el acceso, la utilización y la estabilidad"},{"id":"r2","texto":"Porque los países productores no exportan"},{"id":"r3","texto":"Porque la producción siempre se reparte igual"}]},"solucion":{"valor":false,"explicacion":"Sin acceso económico o físico, sin agua segura o sin estabilidad, puede haber inseguridad alimentaria aunque sobre producción.","clave":["r1"]}},{"slug":"alimentacion-6.s1.p8","orden":8,"grupo":"alimentacion-6.s1.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una encuesta a 400 hogares, el 12 % respondió que algún integrante tuvo que saltearse comidas por falta de dinero en el último año. ¿Cuántos hogares son?","unidad":"hogares","decimales":0,"contexto":"400 hogares encuestados; 12 %."},"solucion":{"valor":48,"tolerancia":0.96,"explicacion":"400 × 12 % = 48 hogares. Datos como estos permiten medir la inseguridad alimentaria y ver si las políticas funcionan. Datos de ejemplo."}},{"slug":"alimentacion-6.s1.p8.v2","orden":8,"grupo":"alimentacion-6.s1.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una encuesta a 1000 hogares, el 8 % respondió que algún integrante tuvo que saltearse comidas por falta de dinero en el último año. ¿Cuántos hogares son?","unidad":"hogares","decimales":0,"contexto":"1000 hogares encuestados; 8 %."},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"1000 × 8 % = 80 hogares. Datos como estos permiten medir la inseguridad alimentaria y ver si las políticas funcionan. Datos de ejemplo."}},{"slug":"alimentacion-6.s1.p8.v3","orden":8,"grupo":"alimentacion-6.s1.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una encuesta a 250 hogares, el 20 % respondió que algún integrante tuvo que saltearse comidas por falta de dinero en el último año. ¿Cuántos hogares son?","unidad":"hogares","decimales":0,"contexto":"250 hogares encuestados; 20 %."},"solucion":{"valor":50,"tolerancia":1,"explicacion":"250 × 20 % = 50 hogares. Datos como estos permiten medir la inseguridad alimentaria y ver si las políticas funcionan. Datos de ejemplo."}},{"slug":"alimentacion-6.s1.p9","orden":9,"grupo":"alimentacion-6.s1.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el agua contaminada afecta la seguridad alimentaria.","items":[{"id":"i1","texto":"Un barrio no tiene agua segura"},{"id":"i2","texto":"Los chicos tienen diarreas frecuentes"},{"id":"i3","texto":"Su cuerpo no aprovecha bien lo que comen"},{"id":"i4","texto":"Aunque coman, se desnutren"},{"id":"i5","texto":"Falla la dimensión de utilización"},{"id":"i6","texto":"El agua contaminada mejora la digestión"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Comer no alcanza si el cuerpo no puede aprovechar lo que come."}},{"slug":"alimentacion-6.s1.p10","orden":10,"grupo":"alimentacion-6.s1.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace falta para que haya seguridad alimentaria? Marcá todo.","opciones":[{"id":"o1","texto":"Que haya alimentos disponibles"},{"id":"o2","texto":"Que las personas puedan pagarlos o acceder a ellos"},{"id":"o3","texto":"Agua segura y salud para aprovecharlos"},{"id":"o4","texto":"Que la situación sea estable en el tiempo"},{"id":"o5","texto":"Que todos coman exactamente lo mismo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Las cuatro dimensiones son necesarias; ninguna alcanza sola."}},{"slug":"alimentacion-6.s1.p11","orden":11,"grupo":"alimentacion-6.s1.p11","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"Una familia gasta el 60 % de su ingreso en comida y cualquier suba de precios la deja sin poder comprar lo necesario. El almacén del barrio está bien surtido. ¿Qué dimensiones están en riesgo? Marcá todas.","opciones":[{"id":"o1","texto":"Acceso"},{"id":"o2","texto":"Estabilidad"},{"id":"o3","texto":"Disponibilidad"},{"id":"o4","texto":"Utilización"}]},"solucion":{"clave":["o1","o2"],"explicacion":"Hay comida en el almacén (disponibilidad), pero el ingreso no alcanza de forma estable: fallan el acceso y la estabilidad."}},{"slug":"alimentacion-6.s1.p12","orden":12,"grupo":"alimentacion-6.s1.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La seguridad alimentaria tiene cuatro dimensiones."},{"id":"s2","texto":"Solo hay inseguridad alimentaria si alguien pasa días enteros sin comer."},{"id":"s3","texto":"El acceso depende de los ingresos y de la cercanía de los comercios."},{"id":"s4","texto":"Un país exportador de alimentos no puede tener hambre."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Entender las dimensiones evita respuestas simplistas.","por_opcion":{"s2":"También incluye comer menos o peor por falta de recursos.","s4":"Puede haber hambre por problemas de acceso aunque sobre producción."}}},{"slug":"alimentacion-6.s1.p13","orden":13,"grupo":"alimentacion-6.s1.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Que haya alimentos es la {{0}}; que las personas puedan conseguirlos es el {{1}}; y que la situación se sostenga en el tiempo es la {{2}}.","banco":[{"id":"w1","texto":"disponibilidad"},{"id":"w2","texto":"acceso"},{"id":"w3","texto":"estabilidad"},{"id":"w4","texto":"cantidad"},{"id":"w5","texto":"precio"},{"id":"w6","texto":"velocidad"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres de las cuatro dimensiones de la seguridad alimentaria."}}]},{"slug":"alimentacion-6.s2","orden":2,"tipo":"leccion","titulo_es":"El hambre en el mundo","bajada_es":"Cuántas personas pasan hambre, cuántas no pueden pagar una dieta saludable y por qué.","minutos":11,"pasos":[{"slug":"alimentacion-6.s2.p1","orden":1,"grupo":"alimentacion-6.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los números","cuerpo":["Según el informe sobre el estado de la seguridad alimentaria y la nutrición en el mundo de 2025, elaborado por la FAO y otras agencias de la ONU, en 2024 unas 673 millones de personas pasaron hambre, alrededor del 8 % de la población mundial. Cerca de 2.300 millones, el 28 %, sufrieron inseguridad alimentaria moderada o grave. Y unas 2.600 millones no podían pagar una dieta saludable. El hambre bajó a nivel mundial y en América Latina, pero siguió creciendo en África y en Asia occidental."],"datos":{"tipo":"barras","titulo":"Personas afectadas en el mundo en 2024 (aproximado)","unidad":"millones","filas":[{"etiqueta":"No pueden pagar una dieta saludable","valor":2600},{"etiqueta":"Inseguridad alimentaria moderada o grave","valor":2300},{"etiqueta":"Hambre","valor":673}],"nota":"FAO, FIDA, OMS, PMA y UNICEF, informe SOFI 2025."}},"solucion":{}},{"slug":"alimentacion-6.s2.p2","orden":2,"grupo":"alimentacion-6.s2.p2","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos indicadores de 2024 según cuántas personas afectan, de más a menos.","items":[{"id":"i1","texto":"No pueden pagar una dieta saludable"},{"id":"i2","texto":"Inseguridad alimentaria moderada o grave"},{"id":"i3","texto":"Hambre"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"Mucha más gente come mal por falta de dinero que la que pasa hambre.","valores":{"i1":"≈ 2.600 millones","i2":"≈ 2.300 millones","i3":"≈ 673 millones"}}},{"slug":"alimentacion-6.s2.p3","orden":3,"grupo":"alimentacion-6.s2.p3","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos millones de personas pasaron hambre en el mundo en 2024, según el informe de la ONU.","min":10,"max":5000,"paso":1,"unidad":"millones","escala":"log"},"solucion":{"valor":673,"banda":"log","explicacion":"Unos 673 millones, alrededor del 8 % de la población mundial."}},{"slug":"alimentacion-6.s2.p4","orden":4,"grupo":"alimentacion-6.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué hay hambre","cuerpo":["Los informes de la ONU señalan varios motores del hambre: los conflictos armados, que destruyen cosechas, mercados y rutas; los eventos climáticos extremos, como sequías e inundaciones; las crisis económicas, que hacen subir los precios y bajar los ingresos; y la desigualdad, que hace que incluso cuando hay comida, muchas personas no puedan acceder a ella. A menudo se combinan."]},"solucion":{}},{"slug":"alimentacion-6.s2.p5","orden":5,"grupo":"alimentacion-6.s2.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué motor del hambre aparece en cada caso?","grupos":[{"id":"g1","nombre":"Conflicto"},{"id":"g2","nombre":"Clima extremo"},{"id":"g3","nombre":"Crisis económica"}],"items":[{"id":"i1","texto":"Una guerra corta las rutas de abastecimiento"},{"id":"i2","texto":"Una sequía arruina la cosecha"},{"id":"i3","texto":"La inflación hace que el sueldo no alcance"},{"id":"i4","texto":"Se destruyen mercados y cultivos"},{"id":"i5","texto":"Una inundación destruye depósitos de alimentos"},{"id":"i6","texto":"Sube de golpe el precio de los alimentos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Los motores del hambre suelen combinarse y reforzarse entre sí."}},{"slug":"alimentacion-6.s2.p6","orden":6,"grupo":"alimentacion-6.s2.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la población mundial es de 8,1 mil millones de personas y el 8,3 % está en una situación dada, ¿cuántos millones de personas son? Redondeá a las decenas de millones.","unidad":"millones","decimales":0,"contexto":"8.1 mil millones de personas; 8.3 %."},"solucion":{"valor":670,"tolerancia":10,"explicacion":"8,1 mil millones × 8,3 % ≈ 670 millones de personas. Un porcentaje \"chico\" del mundo son cientos de millones de personas."}},{"slug":"alimentacion-6.s2.p6.v2","orden":6,"grupo":"alimentacion-6.s2.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la población mundial es de 8,1 mil millones de personas y el 28 % está en una situación dada, ¿cuántos millones de personas son? Redondeá a las decenas de millones.","unidad":"millones","decimales":0,"contexto":"8.1 mil millones de personas; 28 %."},"solucion":{"valor":2270,"tolerancia":10,"explicacion":"8,1 mil millones × 28 % ≈ 2.270 millones de personas. Un porcentaje \"chico\" del mundo son cientos de millones de personas."}},{"slug":"alimentacion-6.s2.p6.v3","orden":6,"grupo":"alimentacion-6.s2.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la población mundial es de 8,2 mil millones de personas y el 32 % está en una situación dada, ¿cuántos millones de personas son? Redondeá a las decenas de millones.","unidad":"millones","decimales":0,"contexto":"8.2 mil millones de personas; 32 %."},"solucion":{"valor":2620,"tolerancia":10,"explicacion":"8,2 mil millones × 32 % ≈ 2.620 millones de personas. Un porcentaje \"chico\" del mundo son cientos de millones de personas."}},{"slug":"alimentacion-6.s2.p7","orden":7,"grupo":"alimentacion-6.s2.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una dieta saludable cuesta","cuerpo":["Una dieta saludable —con frutas, verduras, legumbres, lácteos y proteínas variadas— cuesta más que una dieta que solo cubre las calorías con harinas, azúcares y aceites. Por eso, cuando los ingresos no alcanzan, muchas familias mantienen las calorías pero pierden calidad: comen más ultraprocesados y menos alimentos frescos. Lo viste con los costos ocultos: esa mala alimentación genera enormes costos de salud."]},"solucion":{}},{"slug":"alimentacion-6.s2.p8","orden":8,"grupo":"alimentacion-6.s2.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo la falta de ingresos empeora la dieta.","items":[{"id":"i1","texto":"Suben los precios y no alcanza el ingreso"},{"id":"i2","texto":"La familia prioriza llenar la panza"},{"id":"i3","texto":"Compra más harinas, azúcares y ultraprocesados baratos"},{"id":"i4","texto":"Come menos frutas, verduras y legumbres"},{"id":"i5","texto":"Aumentan los problemas de salud por mala nutrición"},{"id":"i6","texto":"La familia compra más verduras porque son más caras"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cuando el dinero no alcanza, lo primero que se pierde es la calidad."}},{"slug":"alimentacion-6.s2.p9","orden":9,"grupo":"alimentacion-6.s2.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como el hambre bajó a nivel mundial en 2024, bajó en todas las regiones.","razones":[{"id":"r1","texto":"Porque creció en algunas regiones, como África"},{"id":"r2","texto":"Porque el hambre no se mide por región"},{"id":"r3","texto":"Porque subió en todo el mundo"}]},"solucion":{"valor":false,"explicacion":"Bajó en el total y en América Latina, pero siguió creciendo en África y en Asia occidental. Los promedios mundiales esconden diferencias.","clave":["r1"]}},{"slug":"alimentacion-6.s2.p10","orden":10,"grupo":"alimentacion-6.s2.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué hay más personas que no pueden pagar una dieta saludable que personas con hambre?","opciones":[{"id":"o1","texto":"Muchas cubren las calorías, pero no una dieta variada"},{"id":"o2","texto":"Porque la dieta saludable no incluye alimentos"},{"id":"o3","texto":"Porque el hambre se mide con otra moneda"},{"id":"o4","texto":"Porque las personas con hambre comen más variado"}]},"solucion":{"clave":["o1"],"explicacion":"Se puede no pasar hambre y aun así comer mal: la calidad es la primera víctima de los ingresos bajos.","por_opcion":{"o3":"No es una cuestión de moneda: es calidad frente a cantidad."}}},{"slug":"alimentacion-6.s2.p11","orden":11,"grupo":"alimentacion-6.s2.p11","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Hambre"},{"id":"a2","texto":"Inseguridad alimentaria"},{"id":"a3","texto":"Dieta saludable"},{"id":"a4","texto":"Motor del hambre"}],"derecha":[{"id":"b1","texto":"No consumir de forma habitual la energía necesaria"},{"id":"b2","texto":"Comer menos o peor por falta de recursos"},{"id":"b3","texto":"Variada, con frutas, verduras y proteínas"},{"id":"b4","texto":"Causa que empuja a más personas al hambre"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Conceptos para leer los informes sobre hambre con precisión."}},{"slug":"alimentacion-6.s2.p12","orden":12,"grupo":"alimentacion-6.s2.p12","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué factores empujan el hambre en el mundo? Marcá todos.","opciones":[{"id":"o1","texto":"Conflictos armados"},{"id":"o2","texto":"Sequías e inundaciones"},{"id":"o3","texto":"Crisis económicas y suba de precios"},{"id":"o4","texto":"Desigualdad en los ingresos"},{"id":"o5","texto":"El exceso de producción mundial de alimentos"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El mundo produce suficiente comida: el hambre es sobre todo un problema de acceso y de crisis."}},{"slug":"alimentacion-6.s2.p13","orden":13,"grupo":"alimentacion-6.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este posteo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"En 2024, unas 673 millones de personas pasaron hambre."},{"id":"s2","texto":"El hambre existe porque el mundo no produce suficiente comida."},{"id":"s3","texto":"Unas 2.600 millones de personas no podían pagar una dieta saludable."},{"id":"s4","texto":"Una dieta saludable cuesta lo mismo que una basada en harinas y azúcares."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los datos ayudan a desarmar mitos sobre el hambre.","por_opcion":{"s2":"El problema principal es el acceso, junto con conflictos y crisis.","s4":"Suele costar más; por eso los ingresos bajos empeoran la calidad de la dieta."}}},{"slug":"alimentacion-6.s2.p14","orden":14,"grupo":"alimentacion-6.s2.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En 2024, unas {{0}} millones de personas pasaron hambre; cerca del {{1}} % sufrió inseguridad alimentaria moderada o grave; y uno de los motores del hambre son los {{2}} armados.","banco":[{"id":"w1","texto":"673"},{"id":"w2","texto":"28"},{"id":"w3","texto":"conflictos"},{"id":"w4","texto":"67"},{"id":"w5","texto":"2"},{"id":"w6","texto":"deportes"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres datos clave del hambre en el mundo."}}]},{"slug":"alimentacion-6.s3","orden":3,"tipo":"leccion","titulo_es":"Hambre y obesidad a la vez","bajada_es":"La doble carga de la malnutrición, los ultraprocesados y los entornos que empujan a comer peor.","minutos":12,"pasos":[{"slug":"alimentacion-6.s3.p1","orden":1,"grupo":"alimentacion-6.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Malnutrición en todas sus formas","cuerpo":["Malnutrición no es solo desnutrición. Incluye la desnutrición (bajo peso, baja talla, falta de nutrientes), el sobrepeso y la obesidad, y las carencias de vitaminas y minerales, como la anemia por falta de hierro. Muchas veces conviven en un mismo país, en un mismo barrio e incluso en una misma familia: se llama doble carga de la malnutrición."]},"solucion":{}},{"slug":"alimentacion-6.s3.p2","orden":2,"grupo":"alimentacion-6.s3.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué forma de malnutrición es cada caso?","grupos":[{"id":"g1","nombre":"Desnutrición"},{"id":"g2","nombre":"Exceso de peso"},{"id":"g3","nombre":"Carencia de nutrientes"}],"items":[{"id":"i1","texto":"Un chico con baja talla para su edad"},{"id":"i2","texto":"Un adolescente con obesidad"},{"id":"i3","texto":"Una embarazada con anemia por falta de hierro"},{"id":"i4","texto":"Un bebé con bajo peso"},{"id":"i5","texto":"Un adulto con sobrepeso"},{"id":"i6","texto":"Un chico con falta de vitamina A"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Las tres formas pueden convivir en una misma familia."}},{"slug":"alimentacion-6.s3.p3","orden":3,"grupo":"alimentacion-6.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los datos de Argentina","cuerpo":["Según la Segunda Encuesta Nacional de Nutrición y Salud, en Argentina el 67,9 % de los adultos y el 41,1 % de los chicos y adolescentes de 5 a 17 años tenía exceso de peso (sobrepeso u obesidad). Al mismo tiempo, persisten problemas de desnutrición y de anemia en algunos grupos. El exceso de peso es más frecuente en los hogares de menores ingresos, donde los alimentos frescos son relativamente más caros y abundan los ultraprocesados baratos."],"destacado":{"valor":"41,1 %","texto":"de los chicos y adolescentes de 5 a 17 años tenía exceso de peso, según la Segunda Encuesta Nacional de Nutrición y Salud."}},"solucion":{}},{"slug":"alimentacion-6.s3.p4","orden":4,"grupo":"alimentacion-6.s3.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en una escuela hay 500 estudiantes y se aplica la proporción nacional de exceso de peso (41,1 %), ¿cuántos tendrían exceso de peso? Redondeá al entero.","unidad":"estudiantes","decimales":0,"contexto":"500 estudiantes; 41,1 % con exceso de peso."},"solucion":{"valor":206,"tolerancia":1,"explicacion":"500 × 41,1 % ≈ 206 estudiantes. Es un problema colectivo, que tiene que ver con los entornos alimentarios, no solo con decisiones individuales."}},{"slug":"alimentacion-6.s3.p4.v2","orden":4,"grupo":"alimentacion-6.s3.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en una escuela hay 1.200 estudiantes y se aplica la proporción nacional de exceso de peso (41,1 %), ¿cuántos tendrían exceso de peso? Redondeá al entero.","unidad":"estudiantes","decimales":0,"contexto":"1200 estudiantes; 41,1 % con exceso de peso."},"solucion":{"valor":493,"tolerancia":1,"explicacion":"1.200 × 41,1 % ≈ 493 estudiantes. Es un problema colectivo, que tiene que ver con los entornos alimentarios, no solo con decisiones individuales."}},{"slug":"alimentacion-6.s3.p4.v3","orden":4,"grupo":"alimentacion-6.s3.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en una escuela hay 30 estudiantes y se aplica la proporción nacional de exceso de peso (41,1 %), ¿cuántos tendrían exceso de peso? Redondeá al entero.","unidad":"estudiantes","decimales":0,"contexto":"30 estudiantes; 41,1 % con exceso de peso."},"solucion":{"valor":12,"tolerancia":1,"explicacion":"30 × 41,1 % ≈ 12 estudiantes. Es un problema colectivo, que tiene que ver con los entornos alimentarios, no solo con decisiones individuales."}},{"slug":"alimentacion-6.s3.p5","orden":5,"grupo":"alimentacion-6.s3.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Entornos alimentarios","cuerpo":["Lo que comemos no depende solo de cada persona. El entorno alimentario —qué alimentos hay cerca, cuánto cuestan, cómo se publicitan, qué se ofrece en la escuela o en el trabajo— empuja en una dirección. Cuando los ultraprocesados son baratos, están en todas partes y se publicitan dirigidos a chicos, y las frutas y verduras son caras o lejanas, comer bien se vuelve cuesta arriba. Por eso muchas políticas buscan cambiar el entorno: etiquetado frontal, regulación de la publicidad, kioscos saludables en escuelas, agua segura disponible."]},"solucion":{}},{"slug":"alimentacion-6.s3.p6","orden":6,"grupo":"alimentacion-6.s3.p6","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué medidas mejoran el entorno alimentario? Marcá todas.","opciones":[{"id":"o1","texto":"Etiquetado frontal con sellos de advertencia"},{"id":"o2","texto":"Kioscos escolares con opciones saludables"},{"id":"o3","texto":"Bebederos de agua segura en escuelas"},{"id":"o4","texto":"Ferias de frutas y verduras en los barrios"},{"id":"o5","texto":"Publicidad de golosinas dirigida a chicos"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Cambiar el entorno facilita comer bien a todas las personas a la vez."}},{"slug":"alimentacion-6.s3.p7","orden":7,"grupo":"alimentacion-6.s3.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué el exceso de peso suele ser más frecuente en hogares de menores ingresos?","opciones":[{"id":"o1","texto":"Los ultraprocesados baratos abundan y lo fresco es caro"},{"id":"o2","texto":"Porque esas familias no se preocupan por su salud"},{"id":"o3","texto":"Porque comen más frutas y verduras"},{"id":"o4","texto":"Porque tienen más tiempo para cocinar"}]},"solucion":{"clave":["o1"],"explicacion":"El entorno y los precios pesan más que la voluntad individual.","por_opcion":{"o3":"Suelen poder comprar menos alimentos frescos."}}},{"slug":"alimentacion-6.s3.p8","orden":8,"grupo":"alimentacion-6.s3.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El etiquetado frontal","cuerpo":["La Ley 27.642, de Promoción de la Alimentación Saludable, obliga a que los alimentos con exceso de azúcares, sodio, grasas o calorías lleven sellos negros de advertencia en el frente del envase. Además, restringe la publicidad dirigida a chicos de productos con sellos y su venta en las escuelas. Lo viste en la unidad de etiquetas: el objetivo es que la información sea clara y rápida en el momento de elegir."]},"solucion":{}},{"slug":"alimentacion-6.s3.p9","orden":9,"grupo":"alimentacion-6.s3.p9","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada sello con lo que advierte.","izquierda":[{"id":"a1","texto":"Exceso en azúcares"},{"id":"a2","texto":"Exceso en sodio"},{"id":"a3","texto":"Exceso en grasas saturadas"},{"id":"a4","texto":"Exceso en calorías"}],"derecha":[{"id":"b1","texto":"Demasiada azúcar agregada"},{"id":"b2","texto":"Demasiada sal"},{"id":"b3","texto":"Demasiada grasa de ese tipo"},{"id":"b4","texto":"Demasiada energía para la porción"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Los sellos resumen en segundos lo que antes había que buscar en la tabla nutricional."}},{"slug":"alimentacion-6.s3.p10","orden":10,"grupo":"alimentacion-6.s3.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La obesidad es solo un problema de fuerza de voluntad individual.","razones":[{"id":"r1","texto":"Porque el entorno alimentario influye mucho"},{"id":"r2","texto":"Porque la alimentación no tiene relación con el peso"},{"id":"r3","texto":"Porque la voluntad no existe"}]},"solucion":{"valor":false,"explicacion":"Influyen los precios, la publicidad, la disponibilidad de alimentos, el tiempo para cocinar y otros factores del entorno. Por eso hacen falta políticas, no solo consejos.","clave":["r1"]}},{"slug":"alimentacion-6.s3.p11","orden":11,"grupo":"alimentacion-6.s3.p11","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el etiquetado frontal puede cambiar lo que se come.","items":[{"id":"i1","texto":"Los productos con exceso de nutrientes críticos llevan sellos"},{"id":"i2","texto":"Las personas identifican rápido esos excesos"},{"id":"i3","texto":"Muchas eligen opciones con menos sellos"},{"id":"i4","texto":"Algunas empresas reformulan sus productos"},{"id":"i5","texto":"Mejora la calidad de lo que se ofrece y se compra"},{"id":"i6","texto":"Los sellos hacen más baratos los ultraprocesados"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El etiquetado actúa sobre quien compra y también sobre quien produce."}},{"slug":"alimentacion-6.s3.p12","orden":12,"grupo":"alimentacion-6.s3.p12","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de los adultos en Argentina tenía exceso de peso, según la Segunda Encuesta Nacional de Nutrición y Salud.","min":0,"max":100,"paso":0.5,"unidad":"%","escala":"lineal"},"solucion":{"valor":67.9,"banda":"lineal","explicacion":"El 67,9 %: dos de cada tres adultos. Es uno de los mayores problemas de salud pública del país."}},{"slug":"alimentacion-6.s3.p13","orden":13,"grupo":"alimentacion-6.s3.p13","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué forma parte del entorno alimentario de una escuela? Marcá todo.","opciones":[{"id":"o1","texto":"Lo que vende el kiosco"},{"id":"o2","texto":"Si hay bebederos de agua segura"},{"id":"o3","texto":"El menú del comedor"},{"id":"o4","texto":"La publicidad de alimentos en los alrededores"},{"id":"o5","texto":"La cantidad de ventanas de las aulas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El entorno es todo lo que facilita o dificulta comer bien en un lugar."}},{"slug":"alimentacion-6.s3.p14","orden":14,"grupo":"alimentacion-6.s3.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"En Argentina, 4 de cada 10 chicos y adolescentes tienen exceso de peso."},{"id":"s2","texto":"Desnutrición y obesidad nunca conviven en un mismo país."},{"id":"s3","texto":"La Ley 27.642 establece sellos de advertencia en el frente de los envases."},{"id":"s4","texto":"El entorno alimentario no influye en lo que come la gente."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Comer bien es una responsabilidad compartida entre personas, empresas y Estado.","por_opcion":{"s2":"Conviven: es la doble carga de la malnutrición.","s4":"Precios, publicidad y disponibilidad influyen mucho."}}},{"slug":"alimentacion-6.s3.p15","orden":15,"grupo":"alimentacion-6.s3.p15","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Cuando conviven desnutrición y obesidad se habla de doble {{0}}; en Argentina, el {{1}} % de los chicos y adolescentes tiene exceso de peso; y la ley de etiquetado frontal es la Ley {{2}}.","banco":[{"id":"w1","texto":"carga"},{"id":"w2","texto":"41,1"},{"id":"w3","texto":"27.642"},{"id":"w4","texto":"dieta"},{"id":"w5","texto":"4,1"},{"id":"w6","texto":"26.331"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves de la malnutrición en Argentina."}}]},{"slug":"alimentacion-6.s4","orden":4,"tipo":"leccion","titulo_es":"El acceso en Argentina","bajada_es":"Canastas, ingresos, indigencia y la red que sostiene a quienes no llegan: comedores, bancos de alimentos y agricultura familiar.","minutos":11,"pasos":[{"slug":"alimentacion-6.s4.p1","orden":1,"grupo":"alimentacion-6.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Canastas y líneas","cuerpo":["En Argentina, el INDEC mide la pobreza comparando los ingresos de cada hogar con dos canastas. La canasta básica alimentaria incluye los alimentos mínimos para cubrir las necesidades de energía y nutrientes; quienes no llegan a pagarla están en la indigencia. La canasta básica total suma otros bienes y servicios, como transporte, ropa, salud y educación; quienes no llegan a pagarla están en la pobreza.","En el segundo semestre de 2025, en los principales aglomerados urbanos, el 28,2 % de las personas estaba bajo la línea de pobreza y el 6,3 % bajo la línea de indigencia."]},"solucion":{}},{"slug":"alimentacion-6.s4.p2","orden":2,"grupo":"alimentacion-6.s4.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Canasta básica alimentaria"},{"id":"a2","texto":"Canasta básica total"},{"id":"a3","texto":"Indigencia"},{"id":"a4","texto":"Pobreza"}],"derecha":[{"id":"b1","texto":"Alimentos mínimos para cubrir las necesidades nutricionales"},{"id":"b2","texto":"Alimentos más otros bienes y servicios básicos"},{"id":"b3","texto":"Ingresos que no alcanzan la canasta alimentaria"},{"id":"b4","texto":"Ingresos que no alcanzan la canasta total"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"La indigencia es la forma más extrema: no alcanza ni para comer lo mínimo."}},{"slug":"alimentacion-6.s4.p3","orden":3,"grupo":"alimentacion-6.s4.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en los aglomerados urbanos relevados viven unos 30 millones de personas y el 6,3 % está bajo la línea de indigencia, ¿cuántos millones de personas son? Redondeá a un decimal.","unidad":"millones de personas","decimales":1,"contexto":"30 millones de personas; 6.3 %."},"solucion":{"valor":1.9,"tolerancia":0.1,"explicacion":"30 × 6,3 % ≈ 1,9 millones de personas. Detrás de cada punto porcentual hay cientos de miles de personas."}},{"slug":"alimentacion-6.s4.p3.v2","orden":3,"grupo":"alimentacion-6.s4.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en los aglomerados urbanos relevados viven unos 30 millones de personas y el 28,2 % está bajo la línea de pobreza, ¿cuántos millones de personas son? Redondeá a un decimal.","unidad":"millones de personas","decimales":1,"contexto":"30 millones de personas; 28.2 %."},"solucion":{"valor":8.5,"tolerancia":0.1,"explicacion":"30 × 28,2 % ≈ 8,5 millones de personas. Detrás de cada punto porcentual hay cientos de miles de personas."}},{"slug":"alimentacion-6.s4.p3.v3","orden":3,"grupo":"alimentacion-6.s4.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con unos 30 millones de personas en los aglomerados relevados y una indigencia del 6,9 %, ¿cuántos millones de personas no llegan a la canasta alimentaria? Redondeá a un decimal.","unidad":"millones de personas","decimales":1,"contexto":"30 millones de personas; 6.9 %."},"solucion":{"valor":2.1,"tolerancia":0.1,"explicacion":"30 × 6,9 % ≈ 2,1 millones de personas. Detrás de cada punto porcentual hay cientos de miles de personas."}},{"slug":"alimentacion-6.s4.p4","orden":4,"grupo":"alimentacion-6.s4.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La red que sostiene","cuerpo":["Cuando los ingresos no alcanzan, hay una red que sostiene: transferencias del Estado, programas alimentarios, comedores escolares y comunitarios, y bancos de alimentos que recuperan comida apta que se iba a tirar y la distribuyen a organizaciones. La Red Argentina de Bancos de Alimentos reúne a bancos de todo el país. Lo viste con la comida que se tira: recuperar alimentos es a la vez ambiental y social."]},"solucion":{}},{"slug":"alimentacion-6.s4.p5","orden":5,"grupo":"alimentacion-6.s4.p5","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta ayuda actúa sobre los ingresos o entrega alimentos directamente?","grupos":[{"id":"g1","nombre":"Sobre los ingresos"},{"id":"g2","nombre":"Alimentos directos"}],"items":[{"id":"i1","texto":"Transferencias de dinero a hogares con chicos"},{"id":"i2","texto":"Comedores escolares"},{"id":"i3","texto":"Tarjetas para comprar alimentos"},{"id":"i4","texto":"Comedores comunitarios"},{"id":"i5","texto":"Bancos de alimentos que abastecen organizaciones"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Las dos formas se complementan: el dinero da libertad de elegir; la comida directa llega rápido."}},{"slug":"alimentacion-6.s4.p6","orden":6,"grupo":"alimentacion-6.s4.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué ventaja tiene una transferencia de ingresos frente a entregar siempre el mismo bolsón de alimentos?","opciones":[{"id":"o1","texto":"Permite elegir según las necesidades"},{"id":"o2","texto":"Que obliga a comer siempre lo mismo"},{"id":"o3","texto":"Que no tiene ningún costo para el Estado"},{"id":"o4","texto":"Que reemplaza a la escuela"}]},"solucion":{"clave":["o1"],"explicacion":"Cada familia conoce sus necesidades; el dinero permite adaptarse y sostiene al comercio local.","por_opcion":{"o3":"Tiene costo, como cualquier política."}}},{"slug":"alimentacion-6.s4.p7","orden":7,"grupo":"alimentacion-6.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Agricultura familiar","cuerpo":["La agricultura familiar —pequeños productores que trabajan con su familia— produce gran parte de las frutas, verduras, huevos y otros alimentos frescos que llegan a los mercados locales. Fortalecerla, con acceso a tierra, agua, crédito y circuitos de venta directa como ferias, acerca alimentos frescos a los barrios y sostiene economías regionales. Lo viste con los cinturones hortícolas."]},"solucion":{}},{"slug":"alimentacion-6.s4.p8","orden":8,"grupo":"alimentacion-6.s4.p8","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué aporta la agricultura familiar a la seguridad alimentaria? Marcá todo.","opciones":[{"id":"o1","texto":"Alimentos frescos cerca de las ciudades"},{"id":"o2","texto":"Empleo en las economías regionales"},{"id":"o3","texto":"Diversidad de cultivos"},{"id":"o4","texto":"Circuitos cortos como las ferias"},{"id":"o5","texto":"Exportaciones masivas de un solo cultivo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Los alimentos frescos de cercanía dependen mucho de la agricultura familiar."}},{"slug":"alimentacion-6.s4.p9","orden":9,"grupo":"alimentacion-6.s4.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la canasta básica alimentaria de un hogar cuesta 535.991 pesos y su ingreso es de 354.134 pesos, ¿cuántos pesos le faltan para cubrirla?","unidad":"pesos","decimales":0,"contexto":"Canasta alimentaria 535991; ingreso 354134."},"solucion":{"valor":181857,"tolerancia":3637.14,"explicacion":"535.991 − 354.134 = 181.857 pesos. Esa diferencia se llama brecha de la indigencia: cuánto falta para llegar a la canasta alimentaria."}},{"slug":"alimentacion-6.s4.p9.v2","orden":9,"grupo":"alimentacion-6.s4.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la canasta básica alimentaria de un hogar cuesta 500.000 pesos y su ingreso es de 300.000 pesos, ¿cuántos pesos le faltan para cubrirla?","unidad":"pesos","decimales":0,"contexto":"Canasta alimentaria 500000; ingreso 300000."},"solucion":{"valor":200000,"tolerancia":4000,"explicacion":"500.000 − 300.000 = 200.000 pesos. Esa diferencia se llama brecha de la indigencia: cuánto falta para llegar a la canasta alimentaria."}},{"slug":"alimentacion-6.s4.p9.v3","orden":9,"grupo":"alimentacion-6.s4.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la canasta básica alimentaria de un hogar cuesta 600.000 pesos y su ingreso es de 450.000 pesos, ¿cuántos pesos le faltan para cubrirla?","unidad":"pesos","decimales":0,"contexto":"Canasta alimentaria 600000; ingreso 450000."},"solucion":{"valor":150000,"tolerancia":3000,"explicacion":"600.000 − 450.000 = 150.000 pesos. Esa diferencia se llama brecha de la indigencia: cuánto falta para llegar a la canasta alimentaria."}},{"slug":"alimentacion-6.s4.p10","orden":10,"grupo":"alimentacion-6.s4.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Los bancos de alimentos resuelven por sí solos la inseguridad alimentaria de un país.","razones":[{"id":"r1","texto":"Porque depende de ingresos, empleo, precios y políticas"},{"id":"r2","texto":"Porque los bancos de alimentos no distribuyen comida"},{"id":"r3","texto":"Porque la inseguridad alimentaria no existe"}]},"solucion":{"valor":false,"explicacion":"Son una parte valiosa de la red, pero la inseguridad alimentaria depende de los ingresos, el empleo, los precios y las políticas públicas. Ninguna organización sola puede resolverla.","clave":["r1"]}},{"slug":"alimentacion-6.s4.p11","orden":11,"grupo":"alimentacion-6.s4.p11","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de las personas de los principales aglomerados urbanos estaba bajo la línea de indigencia en el segundo semestre de 2025, según el INDEC.","min":0,"max":60,"paso":0.1,"unidad":"%","escala":"lineal"},"solucion":{"valor":6.3,"banda":"lineal","explicacion":"El 6,3 %: casi 1,9 millones de personas cuyos ingresos no alcanzaban para la canasta básica alimentaria."}},{"slug":"alimentacion-6.s4.p12","orden":12,"grupo":"alimentacion-6.s4.p12","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el recorrido de una fruta que llega a un comedor gracias a un banco de alimentos.","items":[{"id":"i1","texto":"Un mercado separa frutas aptas que no se venden por su aspecto"},{"id":"i2","texto":"El banco de alimentos las retira y controla su estado"},{"id":"i3","texto":"Las clasifica y las guarda en condiciones adecuadas"},{"id":"i4","texto":"Las entrega a un comedor comunitario"},{"id":"i5","texto":"Se sirven en el almuerzo del día"},{"id":"i6","texto":"Se tiran al relleno aunque estén aptas"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Recuperar alimentos une el cuidado del ambiente con el derecho a comer."}},{"slug":"alimentacion-6.s4.p13","orden":13,"grupo":"alimentacion-6.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este informe barrial y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La indigencia se mide con la canasta básica alimentaria."},{"id":"s2","texto":"La pobreza y la indigencia son exactamente lo mismo."},{"id":"s3","texto":"Los comedores comunitarios son parte de la red que sostiene."},{"id":"s4","texto":"La agricultura familiar no produce alimentos frescos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer cómo se mide y cómo se sostiene el acceso ayuda a proponer mejor.","por_opcion":{"s2":"La indigencia es no llegar ni a la canasta alimentaria; la pobreza, a la total.","s4":"Produce gran parte de las frutas, verduras y huevos de cercanía."}}},{"slug":"alimentacion-6.s4.p14","orden":14,"grupo":"alimentacion-6.s4.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Quienes no llegan a pagar la canasta básica alimentaria están en la {{0}}; los bancos de alimentos recuperan comida que se iba a {{1}}; y la {{2}} familiar produce gran parte de los alimentos frescos de cercanía.","banco":[{"id":"w1","texto":"indigencia"},{"id":"w2","texto":"tirar"},{"id":"w3","texto":"agricultura"},{"id":"w4","texto":"abundancia"},{"id":"w5","texto":"exportar"},{"id":"w6","texto":"industria"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves del acceso a los alimentos en Argentina."}}]},{"slug":"alimentacion-6.s5","orden":5,"tipo":"leccion","titulo_es":"Sistemas que resisten","bajada_es":"Resiliencia, soberanía alimentaria y cómo preparar el sistema alimentario para crisis climáticas y económicas.","minutos":11,"pasos":[{"slug":"alimentacion-6.s5.p1","orden":1,"grupo":"alimentacion-6.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Resiliencia","cuerpo":["Un sistema alimentario resiliente es el que puede resistir una crisis —una sequía, una pandemia, una suba brusca de precios— y recuperarse sin que la gente pase hambre. Lo hacen más resiliente la diversidad (de cultivos, de productores, de rutas y de proveedores), las reservas, la producción cercana, las redes de protección social y la información a tiempo para actuar antes de que la crisis golpee."]},"solucion":{}},{"slug":"alimentacion-6.s5.p2","orden":2,"grupo":"alimentacion-6.s5.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace más resiliente a un sistema alimentario? Marcá todo.","opciones":[{"id":"o1","texto":"Diversidad de cultivos y productores"},{"id":"o2","texto":"Producción de alimentos cerca de las ciudades"},{"id":"o3","texto":"Redes de protección social que se activan rápido"},{"id":"o4","texto":"Sistemas de alerta temprana"},{"id":"o5","texto":"Depender de un solo proveedor o una sola ruta"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Diversidad, cercanía, protección y anticipación: los ingredientes de la resiliencia."}},{"slug":"alimentacion-6.s5.p3","orden":3,"grupo":"alimentacion-6.s5.p3","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo la diversidad protege el abastecimiento.","items":[{"id":"i1","texto":"Una ciudad compra alimentos de muchas zonas y productores"},{"id":"i2","texto":"Una sequía afecta a una de esas zonas"},{"id":"i3","texto":"Las otras zonas siguen abasteciendo"},{"id":"i4","texto":"Los precios suben menos"},{"id":"i5","texto":"La gente sigue accediendo a los alimentos"},{"id":"i6","texto":"Si falla una zona, falla todo el abastecimiento"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"No depender de una sola fuente reparte el riesgo."}},{"slug":"alimentacion-6.s5.p4","orden":4,"grupo":"alimentacion-6.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Soberanía alimentaria","cuerpo":["El concepto de soberanía alimentaria fue impulsado por movimientos campesinos, como La Vía Campesina, en la década de 1990. Plantea el derecho de los pueblos a definir sus propias políticas alimentarias y a producir sus alimentos de forma sostenible, priorizando la producción local, el acceso a la tierra y al agua, y los saberes de los productores. Complementa la idea de seguridad alimentaria: no solo que haya comida, sino quién la produce, cómo y con qué control."]},"solucion":{}},{"slug":"alimentacion-6.s5.p5","orden":5,"grupo":"alimentacion-6.s5.p5","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿En qué se diferencia la soberanía alimentaria de la seguridad alimentaria?","opciones":[{"id":"o1","texto":"También pregunta quién produce, cómo y con qué control"},{"id":"o2","texto":"En que solo se ocupa de exportar alimentos"},{"id":"o3","texto":"En que rechaza que las personas coman bien"},{"id":"o4","texto":"No hay ninguna diferencia entre las dos ideas"}]},"solucion":{"clave":["o1"],"explicacion":"La seguridad pone el foco en el acceso; la soberanía suma la pregunta sobre el poder y la forma de producir.","por_opcion":{"o3":"Busca justamente que todos coman bien, con otro enfoque."}}},{"slug":"alimentacion-6.s5.p6","orden":6,"grupo":"alimentacion-6.s5.p6","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta idea se asocia más a la seguridad alimentaria o a la soberanía alimentaria?","grupos":[{"id":"g1","nombre":"Seguridad alimentaria"},{"id":"g2","nombre":"Soberanía alimentaria"}],"items":[{"id":"i1","texto":"Que todas las personas tengan acceso a alimentos suficientes"},{"id":"i2","texto":"Derecho de los pueblos a definir sus políticas alimentarias"},{"id":"i3","texto":"Medir el hambre con encuestas"},{"id":"i4","texto":"Acceso de los productores a la tierra y al agua"},{"id":"i5","texto":"Priorizar la producción local y campesina"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Dos enfoques que dialogan y se complementan."}},{"slug":"alimentacion-6.s5.p7","orden":7,"grupo":"alimentacion-6.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Anticiparse","cuerpo":["Los sistemas de alerta temprana combinan pronósticos climáticos, seguimiento de precios y datos de cosechas para detectar una crisis an